#include <iostream>

int main() {
    unsigned int passes = 0;
    unsigned int failures = 0;
    unsigned int student = 1;

    while (student <= 10) {
        int result = 0;
        if (std::cin >> result) {
            if (result == 1) {
                passes = passes + 1;
            } else {
                failures = failures + 1;
            }
            student = student + 1;
        } else {
            break;
        }
    }

    std::cout << "Passed " << passes << "\n";
    std::cout << "Failed " << failures << "\n";

    if (passes > 8) {
        std::cout << "Bonus to instructor!\n";
    }

    return 0;
}

